            if randint(0, 1):
                literals[1] *= -1
            clauses.append(literals)
        return clauses

    def resolution_width(clauses):
        stack = []
        while True:
            new_clause = None
            for i in range(len(stack)):
                for j in range(i+1, len(stack)):
                    if set(stack[i]) & set(stack[j]):
                        new_clause = [l for l in stack[i] + stack[j] if l not in set(stack[i]) & set(stack[j])]
                        break
                if new_clause:
                    break
            if not new_clause:
                return len(set([abs(l) for l in stack]))
            stack.append(new_clause)

    def clifford_algebroid_rank(clauses):
        n = max(abs(l) for clause in clauses for l in clause)
        G = defaultdict(list)
        for clause in clauses:
            for l1 in clause:
                for l2 in clause:
                    if abs(l1) != abs(l2):
                        G[abs(l1)].append((abs(l2), 1))
                        G[abs(l2)].append((abs(l1), 1))
        rank = 0
        visited = set()
        for v in range(1, n+1):
            if v not in visited:
                queue = [v]
                while queue:
                    u = queue.pop(0)
                    if u not in visited:
                        visited.add(u)
                        for neighbor, _ in G[u]:
                            if neighbor not in visited:
                                queue.append(neighbor)
                rank += 1
        return rank

    seed(seed)
