def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def mod_inverse(a, m):
    gcd, x, _ = extended_gcd(a, m)
    if gcd != 1:
        raise ValueError("Inverse doesn't exist")
    else:
        return x % m

def matrix_mul(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def matrix_pow(M, p):
    n = len(M)
    result = [[0 if i != j else 1 for j in range(n)] for i in range(n)]
    while p > 0:
        if p % 2 == 1:
            result = matrix_mul(result, M)
        M = matrix_mul(M, M)
        p //= 2
    return result

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_semidfields(q):
    if q < 4:
        return []
    if q & (q - 1) != 0:
        return []
    p = q.bit_length() - 1
    if not is_prime(p):
        return []
    n = q - 1
    factors = []
    for i in range(2, int(math.sqrt(n)) + 1):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    if len(factors) != 2 or factors[0] * factors[1] != q - 1:
        return []
    a, b = factors
    subfields = []
    for k in range(1, min(a, b) + 1):
        if gcd(k, a) == gcd(k, b) == 1:
            subfields.append(q // (k * k))
    return sorted(subfields)

def generate_primitive_element(q):
    if q < 4:
        return None
    p = q.bit_length() - 1
    if not is_prime(p):
        return None
    n = q - 1
    factors = []
    for i in range(2, int(math.sqrt(n)) + 1):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    if len(factors) != 2 or factors[0] * factors[1] != q - 1:
        return None
    a, b = factors
    for g in range(2, q):
        if pow(g, a, q) == 1 and pow(g, b, q) == 1:
            return g
    return None

def characteristic_function(subgroup):
    n = len(subgroup)
    result = [0] * (n + 1)
    for i in range(n):
        result[subgroup[i]] = 1
    return result

def simulate_acc0_circuit(characteristic, depth):
    n = len(characteristic)
    dp = [[float('inf')] * (1 << n) for _ in range(depth + 1)]
    dp[0][0] = 0
    for d in range(1, depth + 1):
        for state in range(1 << n):
            for i in range(n):
                if (state >> i) & 1:
                    new_state = state ^ (1 << i)
                    cost = dp[d - 1][new_state] + characteristic[i]
                    dp[d][state] = min(dp[d][state], cost)
    return dp[depth][(1 << n) - 1]

