        for j in range(m):
            if j != i:
                factor = augmented_matrix[j][i]
                for k in range(n + 1):
                    augmented_matrix[j][k] = max_plus_add(augmented_matrix[j][k], max_plus_multiply(-factor, augmented_matrix[i][k]))
    return [row[-1] for row in augmented_matrix]

def tropical_rank(matrix):
    m, n = len(matrix), len(matrix[0])
    rank = 0
    for i in range(n):
        pivot_row = -1
        for j in range(m):
            if matrix[j][i] != float('-inf'):
                pivot_row = j
                break
        if pivot_row == -1:
            continue
        rank += 1
        for j in range(m):
            if j != pivot_row:
                factor = max_plus_multiply(-matrix[j][i], matrix[pivot_row][i])
                for k in range(n):
                    matrix[j][k] = max_plus_add(matrix[j][k], max_plus_multiply(factor, matrix[pivot_row][k]))
    return rank

def d_regular_expander_graph(d, n):
    if (d * (n - 1)) % 2 != 0:
        raise ValueError("Invalid parameters for expander graph")
    graph = [[] for _ in range(n)]
    degree = (d * (n - 1)) // 2
    visited = [False] * n
    def dfs(u, count):
        if count == degree:
            return True
        visited[u] = True
        for v in range(n):
            if not visited[v]:
                graph[u].append(v)
                graph[v].append(u)
                if dfs(v, count + 1):
                    return True
                graph[u].pop()
                graph[v].pop()
        visited[u] = False
        return False
    for i in range(n):
        if not visited[i]:
            dfs(i, 0)
    return graph

def incidence_matrix(graph, n):
    m = len(graph)
    A = [[float('-inf')] * n for _ in range(m)]
    for u in range(m):
        for v in graph[u]:
            A[u][v] = 1
    return A

