        new_clauses = []
        for clause in clauses:
            if var in clause:
                new_clauses.append(clause - {var})
            elif -var in clause:
                new_clauses.append(clause | {-var})
        queue.extend(new_clause for new_clause in new_clauses if len(new_clause) == 1)
        clauses = new_clauses
    return max(len(c) for c in clauses)

