    def is_connected(G):
        n = len(G)
        visited = [False] * n
        stack = [0]
        while stack:
            u = stack.pop()
            if not visited[u]:
                visited[u] = True
                for v in range(n):
                    if G[u][v] and not visited[v]:
                        stack.append(v)
