import sys
import random
import math
from itertools import permutations, combinations
from fractions import Fraction

def factorial(n):
    if n == 0:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def hook_walk(n):
    def hook_length_partition(n):
        partition = [n]
        while len(partition) < n:
            new_part = min(partition)
            partition.remove(new_part)
            partition.append(new_part - 1)
            partition.append(1)
        return partition

    def count_inversion_compatible_tableaux(n, partition):
        if n == 1:
            return 1
        count = 0
        for i in range(1, n + 1):
            new_partition = partition[:]
            new_partition[0] -= 1
            new_partition.insert(i - 1, 1)
            count += count_inversion_compatible_tableaux(n - 1, new_partition)
        return count

    partition = hook_length_partition(n)
    return count_inversion_compatible_tableaux(n, partition)

def permanent(matrix):
    n = len(matrix)
    if n == 0:
        return 0
    elif n == 1:
        return matrix[0][0]
    else:
        det = 0
        for j in range(n):
            submatrix = [row[:j] + row[j+1:] for row in matrix[1:]]
            sign = (-1) ** j
            det += sign * matrix[0][j] * permanent(submatrix)
        return det

def determinant(matrix):
    n = len(matrix)
    if n == 0:
        return 0
    elif n == 1:
        return matrix[0][0]
    else:
        det = 0
        for j in range(n):
            submatrix = [row[:j] + row[j+1:] for row in matrix[1:]]
            sign = (-1) ** j
            det += sign * matrix[0][j] * determinant(submatrix)
        return det

def tensor_rank(tensor, eps=1e-9):
    n = len(tensor)
    rank = 0
    while True:
        max_norm = 0
        for i in range(n):
            for j in range(n):
                norm = sum(abs(tensor[k][i][j]) for k in range(n))
                if norm > max_norm:
                    max_norm = norm
                    u = [tensor[k][i][j] / norm for k in range(n)]
                    v = [sum(tensor[k][i][j] * tensor[k][l][j] for k in range(n)) for l in range(n)]
        if max_norm < eps:
            break
        rank += 1
        for i in range(n):
            for j in range(n):
                tensor[i][j] -= u[i] * v[j]
    return rank

def run_trial(seed: int) -> dict:
