import random
import math
import json

def max_plus(a, b):
    return max(a, b)

def min_plus(a, b):
    return min(a, b)

def max_plus_fourier_transform(f, n):
    if n == 1:
        return f[0]
    half_n = n // 2
    even_part = max_plus_fourier_transform([f[2 * i] for i in range(half_n)], half_n)
    odd_part = max_plus_fourier_transform([f[2 * i + 1] for i in range(half_n)], half_n)
    result = [0] * n
    for k in range(n):
        if k < half_n:
            result[k] = max_plus(even_part[k], odd_part[(k - half_n) % half_n])
        else:
            result[k] = min_plus(even_part[k - half_n], odd_part[k - half_n])
    return result

def minimal_fourier_coefficient(f, n):
    fourier_transform = max_plus_fourier_transform(f, 2 ** n)
    return min(fourier_transform)

def run_trial(seed: int) -> dict:
    random.seed(seed)

    n, m = 4, 4
    f_coeffs = [random.uniform(-5, 5) for _ in range(1 << n)]
    g_coeffs = [random.uniform(-5, 5) for _ in range(1 << m)]

    def tropical_polynomial(f, x):
        return sum(f[i] * (-x[i]) for i in range(len(x)))

    f_conv_g = [0] * (1 << (n + m))
    for x in range(1 << n):
        for y in range(1 << m):
            f_val = tropical_polynomial(f_coeffs, list(bin(x)[2:].zfill(n)))
            g_val = tropical_polynomial(g_coeffs, list(bin(y)[2:].zfill(m)))
            f_conv_g[x * (1 << m) + y] = max_plus(f_val + g_val, -x - y)

    min_fc_f = minimal_fourier_coefficient(f_coeffs, n)
    min_fc_g = minimal_fourier_coefficient(g_coeffs, m)
    min_fc_fg = minimal_fourier_coefficient(f_conv_g, n + m)

    disc_f = max_plus_fourier_transform(f_coeffs, 2 ** n)[-1] - min_plus_fourier_transform(f_coeffs, 2 ** n)[0]
    disc_g = max_plus_fourier_transform(g_coeffs, 2 ** m)[-1] - min_plus_fourier_transform(g_coeffs, 2 ** m)[0]
    disc_fg = max_plus_fourier_transform(f_conv_g, 2 ** (n + m))[-1] - min_plus_fourier_transform(f_conv_g, 2 ** (n + m))[0]

    conjecture_holds = abs(min_fc_fg - (min_fc_f + min_fc_g)) < 1e-9 and disc_fg <= disc_f + disc_g + 1e-9
    counterexample = "" if conjecture_holds else "mapping_undefined"

    return {
        "metric_name": "DiscrepancyMeasure",
        "metric_value": disc_fg,
        "instances_tested": 1,
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
    seeds = [int(x) for x in sys.argv[1:]] or [11, 23, 37, 53, 71]

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {json.dumps(result)}")
        results.append(result)

    mean_metric_value = sum(r["metric_value"] for r in results) / len(results)
    std_metric_value = math.sqrt(sum((r["metric_value"] - mean_metric_value) ** 2 for r in results) / len(results))
    support_fraction = sum(1 for r in results if r["conjecture_holds"]) / len(results)

    if all(r["conjecture_holds"] for r in results):
        print(f"RESULT: SUPPORTED mean={mean_metric_value} std={std_metric_value} support_fraction={support_fraction}")
    elif sum(1 for r in results if not r["conjecture_holds"]) / len(results) >= 0.8:
        first_failing_seed = next(r["seed"] for r in results if not r["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample=\"mapping_undefined\" first_failing_seed={first_failing_seed}")
    else:
        print(f"RESULT: INCONCLUSIVE support_fraction={support_fraction}")

import random
import math
import json
from itertools import product

def hadamard(n):
    if n == 1:
        return [[1]]
    H = hadamard(n // 2)
    size = len(H)
    new_H = [[0 for _ in range(size * 2)] for _ in range(size * 2)]
    for i in range(size):
        for j in range(size):
            new_H[i][j] = H[i][j]
            new_H[i][j + size] = H[i][j]
            new_H[i + size][j] = H[i][j]
            new_H[i + size][j + size] = -H[i][j]
    return new_H

def random_bernoulli(n):
    return [[random.choice([-1, 1]) for _ in range(2**n)] for _ in range(2**n)]

def disjointness(n):
    M = [[0 for _ in range(2**n)] for _ in range(2**n)]
    for i in range(2**n):
        M[i][i] = 1
    return M

def planted_low_rank_plus_noise(n, rank=3, noise_level=0.5):
    U = [[random.choice([-1, 1]) for _ in range(rank)] for _ in range(2**n)]
    V = [[random.choice([-1, 1]) for _ in range(rank)] for _ in range(2**n)]
    M = [[sum(U[i][k] * V[j][k] for k in range(rank)) + random.gauss(0, noise_level) for j in range(2**n)] for i in range(2**n)]
    return M

def avg(M, R):
    sum_val = 0
    area = len(R)
    for r in R:
        for c in R:
            sum_val += M[r][c]
    return sum_val / area

def quadratic_variation(M, P):
    total = 0
    for R in P:
        avg_R = avg(M, R)
        if abs(avg_R) > 1/2:
            total += (avg_R ** 2) * len(R)
    return math.sqrt(total)

def generate_partitions(n):
    partitions = []
    for depth in range(1, n + 1):
        current_partition = [[i for i in range(2**n)]]
        while len(current_partition[0]) > 1:
            new_partition = []
            for R in current_partition:
                mid = len(R) // 2
                new_partition.append(R[:mid])
                new_partition.append(R[mid:])
            current_partition = new_partition
        partitions.extend(current_partition)
    return partitions

def discrepancy(M):
    n = int(math.log2(len(M)))
    if n <= 6:
        rectangles = list(product(range(2**n), repeat=4))
        min_disc = float('inf')
        for r1, c1, r2, c2 in rectangles:
            submatrix = [row[c1:c2+1] for row in M[r1:r2+1]]
            avg_val = sum(sum(row) for row in submatrix) / ((r2 - r1 + 1) * (c2 - c1 + 1))
            disc = abs(avg_val)
            if disc < min_disc:
                min_disc = disc
        return min_disc
    else:
        partitions = generate_partitions(n)
        max_disc = 0
        for partition in partitions:
            avg_val = avg(M, partition)
            if abs(avg_val) > 1/2:
                disc = (avg_val ** 2) * len(partition)
                if disc > max_disc:
                    max_disc = disc
        return math.sqrt(max_disc)

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [3, 4, 5, 6, 7, 8, 9, 10]
    results = []

    for n in n_values:
        M = random.choice([hadamard(n), random_bernoulli(n), disjointness(n), planted_low_rank_plus_noise(n)])
        disc_M = discrepancy(M)
        Q_M = quadratic_variation(M, generate_partitions(n))
        r_M = disc_M * 2**n / Q_M
        results.append({
            "metric_name": "discrepancy_ratio",
            "metric_value": r_M,
            "instances_tested": 1,
            "conjecture_holds": r_M >= 0.4,
            "counterexample": "" if r_M >= 0.4 else f"n={n}, disc(M)={disc_M}, Q(M)={Q_M}"
        })

    return {
        "seed": seed,
        "metric_name": "discrepancy_ratio",
        "metric_value": sum(result["metric_value"] for result in results),
        "instances_tested": len(results),
        "conjecture_holds": all(result["conjecture_holds"] for result in results),
        "counterexample": next((result["counterexample"] for result in results if not result["conjecture_holds"]), "")
    }

if __name__ == "__main__":
    seeds = list(map(int, sys.argv[1:])) or [11, 23, 37, 53, 71]
    all_results = []

    for seed in seeds:
        result = run_trial(seed)
        print(json.dumps({"TRIAL": result}))
        all_results.append(result)

    mean_r = sum(result["metric_value"] for result in all_results) / len(all_results)
    support_fraction = sum(1 for result in all_results if result["conjecture_holds"]) / len(all_results)

    if support_fraction >= 0.95:
        print(f"RESULT: SUPPORTED mean={mean_r} std=0 support_fraction={support_fraction}")
    elif any(not result["conjecture_holds"] for result in all_results):
        first_failing_seed = next(seed for seed, result in zip(seeds, all_results) if not result["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample=\"{next(result['counterexample'] for result in all_results if not result['conjecture_holds'])}\" first_failing_seed={first_failing_seed}")
    else:
        print("RESULT: INCONCLUSIVE insufficient data")

import random
import math
import json
from sys import argv

def max_plus(a, b):
    return float('-inf') if a == float('-inf') or b == float('-inf') else max(a, b)

def min_plus(*args):
    return float('inf') if all(x == float('inf') for x in args) else min(args)

def tropical_polynomial(N, slopes, offset):
    f = [0] * N
    current_slope = 0
    for i in range(1, N):
        current_slope += random.uniform(-5, 5)
        f[i] = f[i-1] + current_slope
    return [x + offset for x in f]

def tropical_fourier_transform(f, N):
    F = [float('-inf')] * N
    for k in range(N):
        for x in range(N):
            F[k] = max_plus(F[k], f[x] - k * x)
    return F

def run_trial(seed: int) -> dict:
    random.seed(seed)

    results = []
    for n in [5, 8, 11, 14]:
        N = 2 ** n
        for _ in range(200):
            slopes = sorted(random.uniform(-5, 5) for _ in range(N - 1))
            f = tropical_polynomial(N, slopes, random.uniform(-5, 5))
            F = tropical_fourier_transform(f, N)
            G = tropical_fourier_transform(F, N)

            max_diff = max(abs(G[x] - f[x]) for x in range(N))
            min_fc_f = min_plus(*F)
            min_fc_g = min_plus(*G)
            discrepancy_f = max_plus(*f) - min_plus(*f)
            discrepancy_g = max_plus(*G) - min_plus(*G)

            results.append({
                "n": n,
                "max_diff": max_diff,
                "min_fc_f": min_fc_f,
                "min_fc_g": min_fc_g,
                "discrepancy_f": discrepancy_f,
                "discrepancy_g": discrepancy_g
            })

    all_checks_passed = True
    for result in results:
        if result["max_diff"] >= 1e-9 or abs(result["min_fc_f"] - result["min_fc_g"]) >= 1e-9 or result["discrepancy_g"] > abs(result["min_fc_g"]) + abs(result["discrepancy_f"]):
            all_checks_passed = False
            break

    return {
        "metric_name": "max_diff",
        "metric_value": sum(result["max_diff"] for result in results) / len(results),
        "instances_tested": len(results),
        "conjecture_holds": all_checks_passed,
        "counterexample": "" if all_checks_passed else "involution_failure"
    }

if __name__ == "__main__":
    seeds = [int(x) for x in argv[1:]] or [11, 23, 37, 53, 71]

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {json.dumps(result)}")
        results.append(result)

    mean_metric_value = sum(r["metric_value"] for r in results) / len(results)
    support_fraction = sum(1 for r in results if r["conjecture_holds"]) / len(results)

    if all(r["conjecture_holds"] for r in results):
        print(f"RESULT: SUPPORTED mean={mean_metric_value} std=0.0 support_fraction={support_fraction}")
    elif any(not r["conjecture_holds"] for r in results) and sum(1 for r in results if not r["conjecture_holds"]) / len(results) >= 0.2:
        print(f"RESULT: FALSIFIED counterexample=\"involution_failure\" first_failing_seed={seeds[next(i for i, r in enumerate(results) if not r['conjecture_holds'])]}")
    else:
        print(f"RESULT: INCONCLUSIVE insufficient data to determine support of conjecture")

import random
from itertools import product

def gaussian_elimination(A):
    m, n = len(A), len(A[0])
    rank = 0
    for j in range(n):
        i_max = rank
        for i in range(rank, m):
            if abs(A[i][j]) > abs(A[i_max][j]):
                i_max = i
        A[rank], A[i_max] = A[i_max], A[rank]
        if A[rank][j] != 0:
            factor = 1 / A[rank][j]
            for j2 in range(n):
                A[rank][j2] *= factor
            for i in range(m):
                if i != rank:
                    factor = A[i][j]
                    for j2 in range(n):
                        A[i][j2] -= factor * A[rank][j2]
            rank += 1
    return rank

def matrix_multiplication(A, B):
    m, n, p = len(A), len(B), len(B[0])
    C = [[0 for _ in range(p)] for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for k in range(p):
                C[i][k] += A[i][j] * B[j][k]
    return C

def compute_disc(D, M):
    ℓ = len(M)
    disc = float('inf')
    for coloring in product([-1, 1], repeat=ℓ):
        y = [sum(M[i][j] * coloring[j] for j in range(ℓ)) for i in range(len(D))]
        disc = min(disc, max(abs(y)))
    return disc

def compute_as(f):
    a = len(f)
    count = 0
    for x in product([0, 1], repeat=a):
        for y in product([0, 1], repeat=a):
            if x != y and f(x) == f(y):
                count += 1
    return count / (2 ** a)

def compute_beta(NW_D_f, m):
    n = len(NW_D_f)
    width = (n.bit_length() - 1)
    beta = float('-inf')
    for T in product([0, 1], repeat=n * width):
        T = [T[i:i+width] for i in range(0, n * width, width)]
        pr_s = sum(NW_D_f(s) == 1 for s in product([0, 1], repeat=len(NW_D_f))) / (2 ** len(NW_D_f))
        pr_y = sum(T[y].count(1) / (2 ** y.count(1)) for y in product([0, 1], repeat=n)) / (2 ** n)
        beta = max(beta, abs(pr_s - pr_y))
    return beta

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [6, 8, 11, 14]
    a_values = [2, 3, 4]
    results = []

    for n in n_values:
        for a in a_values:
            m = min(2 * n, 16)
            ℓ = random.randint(5, 16)

            # Generate an (ℓ, a)-NW design
            D = [set() for _ in range(m)]
            while len(D[0]) < a:
                S = set(random.sample(range(ℓ), a))
                if all(len(S.intersection(T)) <= a for T in D):
                    D[random.randint(0, m-1)].update(S)

            # Build the incidence matrix M
            M = [[int(i in S) for i in range(ℓ)] for S in D]

            # Compute disc(D)
            disc = compute_disc(D, M)

            # Define a random Boolean function f
            f = lambda x: random.choice([0, 1])

            # Compute AS(f)
            as_f = compute_as(f)

            # Generate NW_{D,f}
            NW_D_f = [f(tuple(random.choices([0, 1], k=ℓ))) for _ in range(2 ** ℓ)]

            # Compute β(NW_{D,f})
            beta = compute_beta(NW_D_f, m)

            results.append({
                "metric_name": "beta",
                "metric_value": beta,
                "instances_tested": 1,
                "conjecture_holds": beta <= 4 * (disc / m) * 2 ** as_f + 2 ** (-a / 2),
                "counterexample": ""
            })

    mean_beta = sum(result["metric_value"] for result in results) / len(results)
    std_beta = (sum((result["metric_value"] - mean_beta) ** 2 for result in results) / len(results)) ** 0.5
    support_fraction = sum(1 for result in results if result["conjecture_holds"]) / len(results)

    return {
        "seed": seed,
        "mean_beta": mean_beta,
        "std_beta": std_beta,
        "support_fraction": support_fraction,
        "results": results
    }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] or [11, 23, 37, 53, 71]

    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {result}")

    mean_beta = sum(result["mean_beta"] for result in result["results"]) / len(result["results"])
    std_beta = (sum((result["mean_beta"] - mean_beta) ** 2 for result in result["results"]) / len(result["results"])) ** 0.5
    support_fraction = sum(1 for result in result["results"] if result["support_fraction"] >= 0.8) / len(result["results"])

    if support_fraction == 1:
        print(f"RESULT: SUPPORTED mean={mean_beta} std={std_beta} support_fraction={support_fraction}")
    elif support_fraction >= 0.8:
        print("RESULT: INCONCLUSIVE less than 80% seeds support")
    else:
        first_failing_seed = next(seed for seed, result in enumerate(result["results"], start=1) if result["support_fraction"] < 0.8)
