import random
import math
from itertools import combinations

def binomial(n, k):
    if k > n:
        return 0
    res = 1
    for i in range(k):
        res *= (n - i)
        res //= (i + 1)
    return res

def colex_min(n, k):
    return binomial(n, k)

def shadow_defect(F, k):
    n = len(F[0])
    s_F = 0
    for comb in combinations(range(n), k-1):
        shadow = [any(all(F[i][j] == F[j][i] for j in range(k)) for i in comb) for _ in range(len(F))]
        s_F += sum(shadow)
    return s_F - colex_min(len(F), k-1)

def spectral_discrepancy(M_F):
    n = len(M_F)
    max_val = 0
    for x_vec in combinations([-1, 1], n):
        for y_vec in combinations([-1, 1], n):
            val = abs(sum(x_vec[i] * M_F[i][j] * y_vec[j] for j in range(n))) / n**2
            if val > max_val:
                max_val = val
    return max_val

def run_trial(seed: int) -> dict:
    random.seed(seed)
    results = []
    for n in [8, 11, 14]:
        for k in [2, 3, 4]:
            for size in range(binomial(n-1, k-1), binomial(n, k)+1):
                F = [tuple(random.sample(range(n), k)) for _ in range(size)]
                s_F = shadow_defect(F, k)
                M_F = [[1 if set(x) & set(y) == set() else -1 for y in F] for x in F]
                delta_F = spectral_discrepancy(M_F)
                R_F = delta_F * size * binomial(n, k-1) / max(s_F, 1)
                results.append((R_F, F))
    min_R, witness_F = min(results)
    conjecture_holds = min_R >= 0.125
    counterexample = "" if conjecture_holds else f"min(R)={min_R}, witness_F={witness_F}"
    return {
        "metric_name": "R(F)",
        "metric_value": min_R,
        "instances_tested": len(results),
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
    seeds = [int(x) for x in sys.argv[1:]] or [11, 23, 37, 53, 71]
    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {result}")
        results.append(result["metric_value"])

    mean = sum(results) / len(results)
    std_dev = math.sqrt(sum((x - mean)**2 for x in results) / len(results))
    support_fraction = sum(1 for r in results if r >= 0.125) / len(results)
    print(f"RESULT: {'SUPPORTED' if support_fraction >= 0.8 else 'FALSIFIED'} mean={mean} std={std_dev} support_fraction={support_fraction}")

import random
import math
import itertools

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_random_3_regular_graph(n):
        if n % 2 != 0 or n < 4:
            raise ValueError("n must be even and >= 4")
        graph = [[] for _ in range(n)]
        edges = set()
        while len(edges) < n * 3 // 2:
            u, v = random.sample(range(n), 2)
            if (u, v) not in edges and (v, u) not in edges and u != v:
                graph[u].append(v)
                graph[v].append(u)
                edges.add((u, v))
        return graph

    def compute_h(G):
        n = len(G)
        min_cut = float('inf')
        for S in itertools.combinations(range(n), n // 2 + 1):
            cut_size = sum(len([v for v in G[u] if u in S and v not in S]) for u in S)
            min_cut = min(min_cut, cut_size / len(S))
        return min_cut

    def power_iteration(A, k=20):
        n = len(A)
        x = [random.random() for _ in range(n)]
        x /= math.sqrt(sum(x[i] ** 2 for i in range(n)))
        for _ in range(k):
            y = [sum(A[i][j] * x[j] for j in range(n)) for i in range(n)]
            y /= math.sqrt(sum(y[i] ** 2 for i in range(n)))
            x, y = y, x
        return x

    def compute_lambda_2(G):
        n = len(G)
        A = [[0 if u != v else -len(G[u]) + sum(1 for w in G[v] if w != u) for v in range(n)] for u in range(n)]
        eigenvector = power_iteration(A)
        lambda_2 = max(sum(A[i][j] * eigenvector[j] for j in range(n)) * eigenvector[i] for i in range(n))
        return lambda_2

    def compute_delta(G):
        beta_G = 2 * math.sqrt(3 * compute_lambda_2(G))
        h_G = compute_h(G)
        return max(beta_G - h_G, 0)

    def compute_L(G):
        n = len(G)
        delta_G = compute_delta(G)
        beta_G = 2 * math.sqrt(3 * compute_lambda_2(G))
        h_G = compute_h(G)
        return h_G * (1 - delta_G / beta_G) * n // 3 - 2

    def is_valid_clause(clause, assignment):
        return any(assignment[var] == val for var, val in clause)

    def resolve_clause(clause, assignment):
        for i in range(len(clause)):
            if clause[i][1] != assignment[clause[i][0]]:
                new_clause = [c for j, c in enumerate(clause) if j != i]
                return new_clause
        return []

    def dpll(G, n, k, assignment):
        if not any(is_valid_clause(clause, assignment) for clause in G):
            return True
        var = next(v for v in range(n) if v not in assignment)
        for val in [0, 1]:
            new_assignment = assignment.copy()
            new_assignment[var] = val
            if dpll(G, n, k, new_assignment):
                return True
        return False

    def compute_w(G, n, k):
        for w in range(k + 1):
            if all(dpll(G, n, w, {}) for _ in range(30)):
                return w
        return -1

    n = random.choice([8, 10, 12, 14, 16, 18, 20])
    G = generate_random_3_regular_graph(n)
    c = {i: random.randint(0, 1) for i in range(n)}

    h_G = compute_h(G)
    lambda_2_G = compute_lambda_2(G)
    delta_G = compute_delta(G)
    L_G = compute_L(G)

    w_T_G_c = compute_w(G, n, n // 2)

    if w_T_G_c < max(0, L_G) - 1:
        return {
            "metric_name": "w(T(G,c))",
            "metric_value": w_T_G_c,
            "instances_tested": 1,
            "conjecture_holds": False,
            "counterexample": f"Instance {n} with h(G)={h_G}, lambda_2(G)={lambda_2_G}, delta(G)={delta_G}, L(G)={L_G}"
        }

    return {
        "metric_name": "w(T(G,c))",
        "metric_value": w_T_G_c,
        "instances_tested": 1,
        "conjecture_holds": True,
        "counterexample": ""
    }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] or [11, 23, 37, 53, 71]

    results = []
    for seed in seeds:
