        elif node[0] == 'OR':
            stack[-1].extend(stack.pop())
        elif node[0] == 'NOT':
            stack[-1][len(stack[-1]) - 1] = (stack[-1][len(stack[-1]) - 1][0], '1', '0')
        else:
            stack[-1].append((len(stack[-1]) + 1, '0', '1'))
    return stack[0]

def lift_to_f2(triples):
    a = [(1, 2, 3, 4, 5)]
