        elif sigma_true == '1':
            f2_word.extend(b)
        if sigma_false == '0':
            f2_word.extend(b)
        elif sigma_false == '1':
            f2_word.extend(a)
    return reduce_f2_word(f2_word)

def reduce_f2_word(word):
    stack = []
    for letter in word:
        if stack and (stack[-1] == ('a', 'b') or stack[-1] == ('b', 'a')):
            stack.pop()
        else:
