def duval_factorization(s):
    n = len(s)
    i = 0
    factors = []
    while i < n:
        j = i + 1
        k = i
        while j < n and s[j] >= s[k]:
            if s[j] == s[k]:
                k = i
            j += 1
        for _ in range(j - i):
            factors.append(s[i])
            i += 1
    return factors

def leaves(f, memo=None):
    if memo is None:
        memo = {}
    n = len(f)
    if n == 0:
        return 0
    if f in memo:
        return memo[f]
    if all(x == f[0] for x in f) or all(x == f[1] for x in f):
        memo[f] = 1
        return 1
    min_leaves = float('inf')
    for i in range(1, n):
        left = leaves(f[:i], memo)
        right = leaves(f[i:], memo)
        if left + right < min_leaves:
            min_leaves = left + right
    memo[f] = min_leaves
    return min_leaves

def run_trial(seed: int) -> dict:
    random.seed(seed)
