import sys
import random
import math

def gaussian_elimination(A):
    n = len(A)
    m = len(A[0])
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(A[j][i]) > abs(A[max_row][i]):
                max_row = j
        A[i], A[max_row] = A[max_row], A[i]
        if A[i][i] == 0:
            return None  # Singular matrix
        for j in range(i+1, n):
            factor = A[j][i] / A[i][i]
            for k in range(m):
                A[j][k] -= factor * A[i][k]
    rank = sum(1 for row in A if any(row))
    return rank

def boundary_matrix(f, n):
    m = 2**n
    B = [[0]*m for _ in range(n)]
    for i in range(m):
        mask = i
        while mask:
            B[bin(mask).count('1')-1][i] = f[i]
            mask &= (mask - 1)
    return B

def betti_numbers(B, n):
    betti = [0]*n
    for k in range(n):
        ker_dim = gaussian_elimination(B[:k+1])
        if ker_dim is None:
            return None  # Singular matrix
        rank = sum(1 for row in B[k] if any(row))
        betti[k] = ker_dim - rank
    return betti

def dnf_min(f, n):
    m = 2**n
    prime_implicants = []
    for i in range(m):
        mask = i
        while mask:
            if all(f[j] == f[i] for j in range(m) if (j & mask) == mask):
                prime_implicants.append(mask)
            mask &= (mask - 1)
    cover = set()
    for implicant in prime_implicants:
        cover |= {i for i in range(m) if implicant & i == implicant}
    return len(cover)

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [5, 8, 11, 14]
    total_metric_value = 0
    instances_tested = 0
    conjecture_holds = True
