from itertools import combinations

def fibonacci(n):
    fib = [0, 1]
    for i in range(2, n+1):
        fib.append(fib[-1] + fib[-2])
    return fib

def zeckendorf_length(n):
    if n == 0:
        return 0
    fib = fibonacci(n)
    length = 0
    while n > 0:
        for i in range(len(fib)-1, -1, -1):
            if fib[i] <= n:
                n -= fib[i]
                length += 1
                break
    return length

def generate_design(d, m, k, t):
    design = []
    for _ in range(m):
        row = [0]*d
        indices = random.sample(range(d), k)
        for i in indices:
            row[i] = 1
        design.append(row)
    return design

