    max_coeff = 0
    for U in range(1, 2**n):
        coeff = 0
        for i in range(n):
            if U & (1 << i):
                coeff += f[i]
        max_coeff = max(max_coeff, abs(coeff))
    return max_coeff

def compute_bias(d, design, f, T):
    bias = 0
    for s in range(2**d):
        parity = sum(s >> i & 1 for i in T) % 2
        bias += (-1)**parity * f[s]
    return abs(bias / (2**d))

