from itertools import product

def truth_table(f, n):
    inputs = list(product([0, 1], repeat=n))
    outputs = [f(tuple(inputs[i])) for i in range(len(inputs))]
    return outputs

def gray_code(n):
    if n == 0:
        return ['']
    prev_gray = gray_code(n-1)
    return ['0' + code for code in prev_gray] + ['1' + code for code in reversed(prev_gray)]

def factor_complexity(word):
    n = len(word)
    p_w = [0] * (n+1)
    for k in range(1, n+1):
        factors = set()
        for i in range(n-k+1):
            factors.add(word[i:i+k])
        p_w[k] = len(factors)
    return max(p_w) / n

def dnf_min(f, n):
    tt = truth_table(f, n)
    prime_implicants = []
    for i in range(2**n):
        if tt[i]:
            implicant = [i]
            for j in range(i+1, 2**n):
                if (tt[j] and all((j & (1 << k)) == (i & (1 << k)) for k in range(n))):
                    implicant.append(j)
            prime_implicants.append(implicant)
    terms = []
    while prime_implicants:
        selected = None
        for i, imp in enumerate(prime_implicants):
            if not any(all((j & (1 << k)) == (i & (1 << k)) for k in range(n)) for j in imp for other in prime_implicants[i+1:]):
                selected = i
                break
        if selected is None:
            break
        terms.append(prime_implicants[selected])
        prime_implicants = [imp for i, imp in enumerate(prime_implicants) if not any(all((j & (1 << k)) == (i & (1 << k)) for k in range(n)) for j in imp)]
    return len(terms)

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [3, 4, 5, 6]
    total_metric_value = 0
    instances_tested = 0
    conjecture_holds = True
    counterexample = ""

    for n in n_values:
        functions = [(lambda f: lambda x: f(x)) for _ in range(2**n)]
        random.shuffle(functions)
        for f in functions[:5000]:
            w_f = ''.join(str(bit) for bit in truth_table(f, n))
            p_w_f = factor_complexity(w_f)
            DNF_min_f = dnf_min(f, n)
            metric_value = DNF_min_f >= math.ceil(p_w_f / 2)
            total_metric_value += int(metric_value)
            instances_tested += 1
            if not metric_value:
                conjecture_holds = False
                counterexample = f"n={n}, function: {f}"

    return {
        "metric_name": "DNF_min >= ceil(P(f)/2)",
        "metric_value": total_metric_value / instances_tested,
        "instances_tested": instances_tested,
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
    seeds = [int(arg) for arg in sys.argv[1:]] or [11, 23, 37, 53, 71]
    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {json.dumps(result)}")
        results.append(result)

    total_metric_value = sum(res["metric_value"] * res["instances_tested"] for res in results) / sum(res["instances_tested"] for res in results)
    support_fraction = sum(1 for res in results if res["conjecture_holds"]) / len(results)

    if all(res["conjecture_holds"] for res in results):
        print(f"RESULT: SUPPORTED mean={total_metric_value} std=0.0 support_fraction={support_fraction}")
    elif any(not res["conjecture_holds"] for res in results) and any(res["counterexample"] for res in results):
        first_failing_seed = next(res["seed"] for res in results if not res["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample=\"{results[0]['counterexample']}\" first_failing_seed={first_failing_seed}")
    else:
        print("RESULT: INCONCLUSIVE insufficient data")

import random
import math
import sys
import json

def dot_product(a, b):
    return sum(x * y for x, y in zip(a, b))

def matrix_multiply(A, B):
    m = len(A)
    n = len(B[0])
    p = len(B)
    C = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for k in range(p):
                C[i][j] += A[i][k] * B[k][j]
    return C

def hadamard_matrix(n):
    if n == 1:
        return [[1]]
    H = hadamard_matrix(n // 2)
    top_left = H
    top_right = H
    bottom_left = H
    bottom_right = [-x for x in H]
    return [
        [a + b for a, b in zip(top_left, top_right)],
        [a - b for a, b in zip(bottom_left, bottom_right)]
    ]

def rank(matrix):
    n = len(matrix)
    m = len(matrix[0])
    A = [[matrix[i][j] for j in range(m)] for i in range(n)]
    pivot_row = 0
    pivot_col = 0
    while pivot_row < n and pivot_col < m:
        if matrix[pivot_row][pivot_col] == 0:
            swap_found = False
            for i in range(pivot_row + 1, n):
                if matrix[i][pivot_col] != 0:
                    matrix[pivot_row], matrix[i] = matrix[i], matrix[pivot_row]
                    swap_found = True
                    break
            if not swap_found:
                pivot_col += 1
                continue
        for i in range(pivot_row + 1, n):
            factor = -matrix[i][pivot_col] / matrix[pivot_row][pivot_col]
            for j in range(m):
                matrix[i][j] += factor * matrix[pivot_row][j]
        pivot_row += 1
        pivot_col += 1
    return min(pivot_row, m)

def dyadic_discrepancy(M, n):
    max_discrepancy = 0
    for i in range(n):
        for j in range(n):
            box_sum = sum(M[x][y] for x in range(i, min(i + (1 << int(math.log2(n))), n)) for y in range(j, min(j + (1 << int(math.log2(n))), n)))
            discrepancy = abs(box_sum) / math.sqrt((1 << int(math.log2(n))) ** 2)
            if discrepancy > max_discrepancy:
                max_discrepancy = discrepancy
    return max_discrepancy

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [4, 8, 16]
    results = []

    for n in n_values:
        H_n = hadamard_matrix(n)
        D_H_n = dyadic_discrepancy(H_n, n)
        R_H_n_n2 = rank(H_n + [[random.choice([-1, 1]) for _ in range(n)] for _ in range(int(n / 2))])

        results.append({
            "n": n,
            "D_H_n": D_H_n,
            "R_H_n_n2": R_H_n_n2
        })

    return {
        "metric_name": "R(M, n/2) * log(n) / D^2",
        "metric_value": sum(result["R_H_n_n2"] * math.log(result["n"]) / result["D_H_n"] ** 2 for result in results) / len(results),
        "instances_tested": len(results),
        "conjecture_holds": all(result["R_H_n_n2"] * math.log(result["n"]) / result["D_H_n"] ** 2 >= 0.05 for result in results),
        "counterexample": ""
    }

if __name__ == "__main__":
    seeds = [int(s) for s in sys.argv[1:]] if sys.argv[1:] else [11, 23, 37, 53, 71]

    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {json.dumps(result)}")

    # Compute mean/std of metric_value, fraction of seeds where conjecture_holds
    all_results = [run_trial(seed) for seed in seeds]
    mean_metric_value = sum(result["metric_value"] for result in all_results) / len(all_results)
    std_metric_value = math.sqrt(sum((result["metric_value"] - mean_metric_value) ** 2 for result in all_results) / len(all_results))
    support_fraction = sum(1 for result in all_results if result["conjecture_holds"]) / len(all_results)

    if support_fraction >= 0.9:
        print(f"RESULT: SUPPORTED mean={mean_metric_value} std={std_metric_value} support_fraction={support_fraction}")
    else:
        first_failing_seed = next(seed for seed, result in enumerate(all_results) if not result["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample=\"first failing seed\" first_failing_seed={first_failing_seed}")

import random
import json
from collections import defaultdict

def hamming_distance(x, y):
    return sum(xi != yi for xi, yi in zip(x, y))

def build_cochain_complex(G):
    n = len(G)
    E_bi = []
    T_bi = []
    for i in range(n):
        for j in G[i]:
            for k in G[j]:
                if hamming_distance(i, k) <= 2:
                    E_bi.append((i, j, k))
                    T_bi.append((i, j, k))
    return E_bi, T_bi

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [3, 4, 5, 6]
    h1_counts = defaultdict(int)
    h1_positive_probabilities = []

    for n in n_values:
        X = [''.join(random.choice('01') for _ in range(n)) for _ in range(2**n)]
        G = {i: [j for j in range(len(X)) if hamming_distance(i, j) <= 1] for i in range(len(X))}

        E_bi, T_bi = build_cochain_complex(G)
        delta_0 = [[0] * len(E_bi) for _ in range(2**n)]
        delta_1 = [[0] * len(T_bi) for _ in range(len(E_bi))]

        for i in range(len(X)):
            for j in G[i]:
                if (i, j, k) in E_bi:
                    delta_0[i][E_bi.index((i, j, k))] += 1
                    delta_1[E_bi.index((i, j, k))][T_bi.index((i, j, k))] += 1

        ker_delta_1 = [sum(row) == 0 for row in delta_1]
        rank_delta_0 = sum(1 for row in delta_0 if any(x != 0 for x in row))

        h1 = sum(ker_delta_1) - rank_delta_0
        h1_counts[n] += h1
        h1_positive_probabilities.append(h1 > 0)

    empirical_mean_h1 = {n: h1_counts[n] / (2**n * 200) for n in n_values}
    fraction_positive_h1 = sum(h1_positive_probabilities) / len(n_values)

    conjecture_holds = all(empirical_mean_h1[n] <= 0.5 for n in n_values)
    counterexample = "" if conjecture_holds else "h^1(f) > 0 for some random f"

    return {
        "metric_name": "Pr[h^1(f)>0]",
        "metric_value": fraction_positive_h1,
        "instances_tested": len(n_values),
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
    seeds = [int(x) for x in sys.argv[1:]] if len(sys.argv) > 1 else [11, 23, 37, 53, 71]

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {json.dumps(result)}")
        results.append(result)

    mean_h1 = sum(result["metric_value"] for result in results) / len(results)
    std_h1 = (sum((result["metric_value"] - mean_h1) ** 2 for result in results) / len(results)) ** 0.5
    support_fraction = sum(1 for result in results if result["conjecture_holds"]) / len(results)

    if all(result["conjecture_holds"] for result in results):
        print(f"RESULT: SUPPORTED mean={mean_h1} std={std_h1} support_fraction={support_fraction}")
    elif sum(1 for result in results if not result["conjecture_holds"]) >= len(results) * 0.2:
        first_failing_seed = next(seed for seed, result in zip(seeds, results) if not result["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample=\"h^1(f) > 0 for some random f\" first_failing_seed={first_failing_seed}")
    else:
        print("RESULT: INCONCLUSIVE insufficient evidence")

import random
import math
import json

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_boolean_function(n):
        return [random.choice([0, 1]) for _ in range(2**n)]

    def truth_table_to_dict(tt):
        n = int(math.log2(len(tt)))
        table = {}
        for i in range(len(tt)):
            inputs = tuple((i >> j) & 1 for j in range(n))
            outputs = tt[i]
            if inputs not in table:
                table[inputs] = []
            table[inputs].append(outputs)
        return table

    def prime_implicant_enumeration(f):
        n = int(math.log2(len(f)))
        table = truth_table_to_dict(f)
        implicants = []
        for inputs, outputs in table.items():
            if len(set(outputs)) == 1:
                implicants.append(inputs)
        return implicants

    def build_poset(implicants):
        poset = {}
        for i in range(len(implicants)):
            for j in range(i + 1, len(implicants)):
                a, b = implicants[i], implicants[j]
                if all(a[k] == b[k] or a[k] == 0 for k in range(len(a))):
                    poset.setdefault(a, []).append(b)
        return poset

    def maximum_bipartite_matching(graph):
        n = len(graph)
        matching = [-1] * n
        visited = [False] * n

        def dfs(u):
            for v in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    if matching[v] == -1 or dfs(matching[v]):
                        matching[v] = u
                        return True
            return False

        for u in range(n):
            visited = [False] * n
            dfs(u)

        return sum(1 for x in matching if x != -1) // 2

    def memoized_minimax(f, depth=0, cache=None):
        if cache is None:
            cache = {}
        n = int(math.log2(len(f)))
        key = (tuple(f), depth)
        if key in cache:
            return cache[key]

        if depth == n:
            return 1

        min_val = float('inf')
        for i in range(n):
            left = f[:i] + [0] * (n - i) + f[i+1:]
            right = f[:i] + [1] * (n - i) + f[i+1:]
            min_val = min(min_val, max(memoized_minimax(left, depth + 1, cache), memoized_minimax(right, depth + 1, cache)))

        cache[key] = min_val
        return min_val

    def ind_lift(f, b):
        n = int(math.log2(len(f)))
        protocol_tree = {}
        for i in range(n):
            left = f[:i] + [0] * (n - i) + f[i+1:]
            right = f[:i] + [1] * (n - i) + f[i+1:]
            protocol_tree[(i, 0)] = memoized_minimax(left)
            protocol_tree[(i, 1)] = memoized_minimax(right)

        def dfs(node, depth):
            if node in protocol_tree:
                return protocol_tree[node]
            min_val = float('inf')
            for i in range(n):
                left = f[:i] + [0] * (n - i) + f[i+1:]
                right = f[:i] + [1] * (n - i) + f[i+1:]
                min_val = min(min_val, max(dfs((i, 0), depth + 1), dfs((i, 1), depth + 1)))
            return min_val

        return dfs((0, 0), 0)

    n = random.randint(3, 12)
    f = generate_boolean_function(n)
    implicants = prime_implicant_enumeration(f)
    poset = build_poset(implicants)
    w_f = maximum_bipartite_matching(poset)
    q_dt_f = memoized_minimax(f)

    conjecture_holds = q_dt_f >= math.ceil(math.log2(w_f + 1))
    counterexample = "" if conjecture_holds else f"Counterexample for n={n}, w(f)={w_f}, Q^dt(f)={q_dt_f}"

    return {
        "metric_name": "Q^dt(f)",
        "metric_value": q_dt_f,
        "instances_tested": 1,
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
    seeds = [int(x) for x in sys.argv[1:]] or [11, 23, 37, 53, 71]

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(json.dumps({"TRIAL": {"seed": seed, **result}}))
        results.append(result)

    mean_q_dt_f = sum(r["metric_value"] for r in results) / len(results)
    std_q_dt_f = math.sqrt(sum((r["metric_value"] - mean_q_dt_f) ** 2 for r in results) / len(results))
    support_fraction = sum(1 for r in results if r["conjecture_holds"]) / len(results)

    if all(r["conjecture_holds"] for r in results):
        print(f"RESULT: SUPPORTED mean={mean_q_dt_f} std={std_q_dt_f} support_fraction={support_fraction}")
    elif sum(1 for r in results if not r["conjecture_holds"]) / len(results) >= 0.2:
        print("RESULT: FALSIFIED counterexample=\"\" first_failing_seed=0")
    else:
        print(f"RESULT: INCONCLUSIVE support_fraction={support_fraction}")

import random
import math
import sys
import json

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def matrix_multiply(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def gaussian_elimination(M, b):
    n = len(M)
    M_b = [row + [b[i]] for i, row in enumerate(M)]
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(M[j][i]) > abs(M[max_row][i]):
                max_row = j
        M_b[i], M_b[max_row] = M_b[max_row], M_b[i]
        pivot = M_b[i][i]
        for j in range(n + 1):
            M_b[i][j] /= pivot
        for j in range(n):
            if i != j:
                factor = M_b[j][i]
                for k in range(n + 1):
                    M_b[j][k] -= factor * M_b[i][k]
    return [row[-1] for row in M_b]

def squarefree_reduction(poly, n):
    result = {}
    for term, coeff in poly.items():
        mask = 0
        for var, sign in enumerate(term):
            if sign > 0:
                mask |= (1 << var)
            else:
                mask &= ~(1 << var)
        result[mask] += coeff
    return result

def derivative(poly, var, n):
    result = {}
    for term, coeff in poly.items():
        new_term = []
        for i in range(n):
            if i != var:
                new_term.append((term[i], term[i]))
        result[tuple(new_term)] += coeff * (1 - 2 * (var + 1 in term))
    return result

def dpll(F, assignment, n):
    if not F:
        return True
    for clause in F:
        if all(lit in assignment and assignment[lit] == sign for lit, sign in clause):
            continue
        for var, sign in clause:
            new_assignment = assignment.copy()
            new_assignment[var + 1 if sign > 0 else -(var + 1)] = sign
            if dpll(F - {tuple(sorted([var + 1 if sign > 0 else -(var + 1) for sign, var in clause])) for clause in F if var + 1 in clause}, new_assignment, n):
                return True
        return False

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_3cnf(n, m):
        variables = list(range(1, n + 1))
        clauses = []
        for _ in range(m):
            clause = []
            for _ in range(3):
                var = random.choice(variables)
                sign = random.choice([1, -1])
                if (var, sign) not in clause and (-var, -sign) not in clause:
                    clause.append((var, sign))
            clauses.append(tuple(sorted(clause)))
        return set(clauses)

    def is_unsat(F, n):
        assignment = {}
        return not dpll(F, assignment, n)

    n_values = [8, 10]
    m_values = [42, 50]

    for n in n_values:
        for m in m_values:
            F = generate_3cnf(n, m)
            if is_unsat(F, n):
                D_F = dpll(F, {}, n)
                if D_F < 8:
                    continue
                f_F = {}
                for clause in F:
                    L_C = {tuple(sorted([var + 1 if sign > 0 else -(var + 1) for sign, var in clause])): 1}
                    for C_prime in F - {clause}:
                        L_C = squarefree_reduction(derivative(L_C, var, n), n)
                π_F = {}
                for term, coeff in f_F.items():
                    mask = 0
                    for var, sign in enumerate(term):
                        if sign > 0:
                            mask |= (1 << var)
                        else:
                            mask &= ~(1 << var)
                    π_F[mask] += coeff
                μ_F = []
                for i in range(n):
                    ψ_i = sum(s(C, i) * π_F[tuple(sorted([var + 1 if sign > 0 else -(var + 1) for sign, var in clause]))] for C in F)
                    μ_F.append(ψ_i)
                rank = len(set(gaussian_elimination([[term[i] for term in μ_F] for i in range(n)], [0] * n)))
                if rank < math.ceil(math.log2(D_F)):
                    return {
                        "metric_name": "μ(F)",
                        "metric_value": rank,
                        "instances_tested": 1,
                        "conjecture_holds": False,
                        "counterexample": f"n={n}, m={m}, D_F={D_F}"
                    }
    return {
        "metric_name": "μ(F)",
        "metric_value": 0,
        "instances_tested": 0,
        "conjecture_holds": True,
        "counterexample": ""
    }

if __name__ == "__main__":
    seeds = [int(s) for s in sys.argv[1:]] or [11, 23, 37, 53, 71]
    results = []

    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {json.dumps(result)}")
        results.append(result)

    total_metric_value = sum(r["metric_value"] for r in results if "metric_value" in r)
    support_fraction = sum(1 for r in results if r["conjecture_holds"])

    if all(r["conjecture_holds"] for r in results) or support_fraction / len(results) >= 0.9:
        print(f"RESULT: SUPPORTED mean={total_metric_value/len(results):.2f} std=0.00 support_fraction={support_fraction/len(results):.2f}")
    elif any(not r["conjecture_holds"] for r in results):
        first_failing_seed = next(seed for seed, result in zip(seeds, results) if not result["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample=\"{result['counterexample']}\" first_failing_seed={first_failing_seed}")
    else:
        print("RESULT: INCONCLUSIVE insufficient data")

import sys
import random
import math

def is_connected(graph):
    n = len(graph)
    visited = [False] * n
    stack = [0]
    visited[0] = True

    while stack:
        u = stack.pop()
        for v in range(n):
            if graph[u][v] and not visited[v]:
                visited[v] = True
                stack.append(v)

    return all(visited)

def generate_3_regular_graph(n):
    if n % 2 == 0 or (n * (n - 1) // 2) % 6 != 0:
        raise ValueError("Invalid number of vertices for a 3-regular graph")

    graph = [[0] * n for _ in range(n)]
    degree = [0] * n

    def add_edge(u, v):
        if u == v or graph[u][v]:
            return
        graph[u][v] = 1
        graph[v][u] = 1
        degree[u] += 1
        degree[v] += 1

    for _ in range(n * (n - 1) // 6):
        u, v = random.sample(range(n), 2)
        if degree[u] < 3 and degree[v] < 3:
            add_edge(u, v)

    return graph

def generate_odd_charges(n):
    return [random.choice([0, 1]) for _ in range(n)]

def partition_vertex_set(vertices, k):
    n = len(vertices)
    if k > n:
        return []

    partitions = []
    for i in range(2 ** (n - 1)):
        part1 = [vertices[j] for j in range(n) if i & (1 << j)]
        part2 = [v for v in vertices if v not in part1]
        partitions.append((part1, part2))

    return partitions

def compute_h_q(G):
    n = len(G)
    min_cut_edges = float('inf')
    min_partition_size = float('inf')

    for k in range(2, n + 1):
        partitions = partition_vertex_set(range(n), k)
        for part1, part2 in partitions:
            cut_edges = sum(G[u][v] for u in part1 for v in part2 if G[u][v])
            min_cut_edges = min(min_cut_edges, cut_edges)
            min_partition_size = min(min_partition_size, len(part1), len(part2))

    return min_cut_edges / min_partition_size

def bfs_width(G, start):
    n = len(G)
    visited = [False] * n
    queue = [start]
    visited[start] = True

    width = 0
    while queue:
        level_size = len(queue)
        for _ in range(level_size):
            u = queue.pop(0)
            for v in range(n):
                if G[u][v] and not visited[v]:
                    visited[v] = True
                    queue.append(v)

        width = max(width, level_size)

    return width

