    n = 16
    cache = {}

    def helper(x):
        if x not in cache:
            if len(x) == 1:
                return 0
            else:
                left = helper([f(xi, 0) for xi in range(n)])
                right = helper([f(xi, 1) for xi in range(n)])
                cache[x] = 1 + max(left, right)
        return cache[x]

    return helper(tuple(range(n)))

def RSK_insertion_tableau(arr):
    shape = [0]
    stack = []
    for x in arr:
        i = bisect_right(stack, x)
        if i == len(stack):
            stack.append(x)
            shape[-1] += 1
        else:
            stack[i] = x
    return shape

