def binomial(n, k):
    if k > n:
        return 0
    result = 1
    for i in range(k):
        result *= (n - i)
        result //= (i + 1)
    return result

def hamming_weight(x):
    return bin(x).count('1')

def A_w(f, w):
    n = len(f)
    return sum(f(x) * (-1)**hamming_weight(x) for x in range(2**n) if hamming_weight(x) == w) / binomial(n, w)

