                if is_unsat(clause):
                    clauses.append(clause)
            if len(clauses) == m and not dpll(clauses, [None] * n):
                unsat_count += 1
                g_F = [[l + (n if l < 0 else -n) for l in c] for c in clauses]
                delta = compute_delta(g_F)
                d_T = memoized_minimax(clauses, [None] * n)
                if d_T >= math.ceil(delta):
