        Y = [(i & (1 << j)) == 0 for i in range(2**n) for j in range(n)]
        return min(max([sum(X[i] and Y[j] for i, j in zip(range(2**n), range(2**n))) for i in range(2**n)]), n)

    def compute_pd(f, n):
