import random
import math
from fractions import Fraction

def binomial(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    c = Fraction(1, 1)
    for i in range(1, k + 1):
        c *= (n - i + 1) / i
    return c

def gaussian_elimination(M):
    m, n = len(M), len(M[0])
    rank = 0
    for j in range(n):
        pivot_row = None
        for i in range(rank, m):
            if M[i][j] != 0:
                pivot_row = i
                break
        if pivot_row is None:
            continue
        M[pivot_row], M[rank] = M[rank], M[pivot_row]
        rank += 1
        for i in range(rank, m):
            factor = -M[i][j] / M[rank-1][j]
            for k in range(j, n):
                M[i][k] += factor * M[rank-1][k]
    return rank

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [8, 10, 12, 14, 16]
    results = []

    for n in n_values:
        L_DPLL = 0
        for _ in range(200):
            # Generate a random UNSAT 3-CNF formula with α=4.5
            clauses = []
            for i in range(n * (n - 1) // 2):
                clause = [random.choice([-1, 1]) * random.randint(1, n) for _ in range(3)]
                if len(set(clause)) == 3:
                    clauses.append(clause)
            F = clauses

            # Compute p_F
            p_F_coeffs = [[0] * (n + 2) for _ in range(n + 2)]
            for clause in F:
                i1, i2, i3 = sorted(abs(lit) - 1 for lit in clause)
                sign = (-1) ** sum(lit < 0 for lit in clause)
                p_F_coeffs[i1][i2] += sign
                p_F_coeffs[i1][i3] += sign
                p_F_coeffs[i2][i3] += sign

            # Construct the constraint matrix M
            M = [[0] * (n**2) for _ in range(binomial(n+2, 3))]
            for i in range(1, n + 2):
                for j in range(i + 1, n + 2):
                    for k in range(j + 1, n + 2):
                        index = binomial(i-1, 2) * (n - i + 1) // 2 + binomial(j-i, 2)
                        M[index][i*n+j-1] += p_F_coeffs[i][j]
                        M[index][i*n+k-1] += p_F_coeffs[i][k]
                        M[index][(j-1)*n+k-1] += p_F_coeffs[j][k]

            # Compute dim_Q(g_F)
            rank = gaussian_elimination(M)
            g_F_dim = n**2 - rank

            # Run lex-DPLL to count L_DPLL(F)
            def dpll(clauses, assignment):
                if not clauses:
                    return 1
                unit_clauses = [c for c in clauses if len(c) == 1]
                if unit_clauses:
                    lit = unit_clauses[0][0]
                    new_assignment = assignment.copy()
                    new_assignment[lit] = True
                    if all(assignment[lit] == (lit > 0) or assignment[-lit] == (lit < 0) for lit in [c[0] for c in clauses]):
                        return dpll([c for c in clauses if lit not in c], new_assignment)
                    else:
                        return 0
                literals = set(lit for clause in clauses for lit in clause)
                for lit in literals:
                    new_assignment = assignment.copy()
                    new_assignment[lit] = True
                    if all(assignment[lit] == (lit > 0) or assignment[-lit] == (lit < 0) for lit in [c[0] for c in clauses]):
                        count = dpll([c for c in clauses if lit not in c], new_assignment)
                        if count > 0:
                            return count
                    new_assignment[lit] = False
                    if all(assignment[lit] == (lit > 0) or assignment[-lit] == (lit < 0) for lit in [c[0] for c in clauses]):
                        count = dpll([c for c in clauses if lit not in c], new_assignment)
                        if count > 0:
                            return count
                return 0

            L_DPLL += dpll(F, {})

        results.append({
            "n": n,
            "L_DPLL": L_DPLL,
            "g_F_dim": g_F_dim
        })

    max_delta = max(math.log2(result["L_DPLL"]) + result["g_F_dim"] - (result["n"] + 2 * math.ceil(math.log2(result["n"]))) for result in results)
    conjecture_holds = max_delta <= 0
    counterexample = "" if conjecture_holds else "max Δ(F) > 1"

    return {
        "metric_name": "Δ(F)",
        "metric_value": max_delta,
        "instances_tested": len(results),
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
    seeds = [int(arg) for arg in sys.argv[1:]] or [11, 23, 37, 53, 71]

    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {result}")

    # Compute mean/std of metric_value and fraction of seeds where conjecture_holds
    total_metric_value = sum(result["metric_value"] for result in results)
    mean_metric_value = total_metric_value / len(results)

    squared_diff_sum = sum((result["metric_value"] - mean_metric_value) ** 2 for result in results)
    std_metric_value = math.sqrt(squared_diff_sum / len(results))

    support_fraction = sum(1 for result in results if result["conjecture_holds"]) / len(results)

    if all(result["conjecture_holds"] for result in results):
        print(f"RESULT: SUPPORTED mean={mean_metric_value} std={std_metric_value} support_fraction=1.0")
    elif sum(1 for result in results if not result["conjecture_holds"]) / len(results) >= 0.8:
        print(f"RESULT: SUPPORTED mean={mean_metric_value} std={std_metric_value} support_fraction={support_fraction}")
    else:
        first_failing_seed = next(seed for seed, result in enumerate(results) if not result["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample=\"max Δ(F) > 1\" first_failing_seed={first_failing_seed + 1}")

import random
import math
from collections import defaultdict

# Implement basic linear algebra operations manually
def matrix_multiply(A, B):
    m = len(A)
    n = len(B[0])
    p = len(B)
    C = [[0 for _ in range(n)] for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for k in range(p):
                C[i][j] += A[i][k] * B[k][j]
    return C

def gaussian_elimination(A, b):
    n = len(A)
    M = [A[i] + b[i] for i in range(n)]
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(M[j][i]) > abs(M[max_row][i]):
                max_row = j
        M[i], M[max_row] = M[max_row], M[i]
        for j in range(i+1, n):
            factor = M[j][i] / M[i][i]
            M[j] = [M[j][k] - factor * M[i][k] for k in range(n)]
    x = [0] * n
    for i in range(n-1, -1, -1):
        x[i] = M[i][-1]
        for j in range(i+1, n):
            x[i] -= M[i][j] * x[j]
        x[i] /= M[i][i]
    return x

def hamming_distance(a, b):
    return sum(1 for i in range(len(a)) if a[i] != b[i])

# Define the MetricGadget class
class MetricGadget:
    def __init__(self, X, Y, g, d):
        self.X = X
        self.Y = Y
        self.g = g
        self.d = d

    def distance(self, x1, y1, x2, y2):
        return self.d(x1, y1) + self.d(x2, y2)

# Implement the Følner defect calculation
def folner_defect(G, R, n):
    X, Y, g, d = G.X, G.Y, G.g, G.d
    k = len(X)
    total_points = k ** (2 * n)
    min_boundary_ratio = float('inf')

    for F in range(total_points):
        boundary_count = 0
        for i in range(n):
            x1, y1 = X[F % k], Y[(F // k) % k]
            x2, y2 = X[(F + 1) % k], Y[((F + 1) // k) % k]
            if d(x1, x2) > R or d(y1, y2) > R:
                boundary_count += 1
        min_boundary_ratio = min(min_boundary_ratio, boundary_count / total_points)

    return min_boundary_ratio

# Implement the CC(EQ_k ∘ G^n) calculation using rank/partition-bound LP
def cc_eqk_gn(G, n):
    X, Y, g, d = G.X, G.Y, G.g, G.d
    k = len(X)
    m = 2 ** (n * math.log2(k))

    # Construct the communication matrix
    C = [[0 for _ in range(m)] for _ in range(m)]
    for i in range(m):
        x1, y1 = X[i % k], Y[(i // k) % k]
        for j in range(m):
            x2, y2 = X[j % k], Y[(j // k) % k]
            C[i][j] = d(x1, x2) + d(y1, y2)

    # Solve the rank/partition-bound LP
    b = [0 for _ in range(m)]
    A = [[0 for _ in range(m)] for _ in range(m)]
    for i in range(m):
        for j in range(m):
            if i != j:
                A[i][j] = C[i][j]

    x = gaussian_elimination(A, b)
    return sum(x)

# Define the run_trial function
def run_trial(seed: int) -> dict:
    random.seed(seed)
    k_values = [2, 3, 4]
    n_values = [1, 2, 3, 4]

    results = []
    for k in k_values:
        X = [f"x{i}" for i in range(k)]
        Y = [f"y{i}" for i in range(k)]
        g = lambda x, y: hamming_distance(x, y)
        d = lambda a, b: sum(1 for i in range(len(a)) if a[i] != b[i])
        G = MetricGadget(X, Y, g, d)

        for n in n_values:
            R = math.inf  # Diameter of the gadget
            m_n = folner_defect(G, R, n)
            cc_eqk_gn_value = cc_eqk_gn(G, n)

            results.append({
                "metric_name": "CC(EQ_k ∘ G^n)",
                "metric_value": cc_eqk_gn_value,
                "instances_tested": 1,
                "conjecture_holds": cc_eqk_gn_value >= n * math.log2(m_n + 1),
                "counterexample": ""
            })

    mean_metric_value = sum(result["metric_value"] for result in results) / len(results)
    support_fraction = sum(1 for result in results if result["conjecture_holds"]) / len(results)

    return {
        "seed": seed,
        "mean_metric_value": mean_metric_value,
        "support_fraction": support_fraction
    }

# Main block to run trials and print results
if __name__ == "__main__":
    seeds = [11, 23, 37, 53, 71] if len(sys.argv) < 2 else [int(arg) for arg in sys.argv[1:]]

    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {result}")

    # Compute mean and support fraction across all seeds
    total_results = []
    for seed in seeds:
        with open(f"trial_{seed}.json", "r") as f:
            trial_result = json.load(f)
            total_results.append(trial_result)

    mean_metric_value = sum(result["mean_metric_value"] for result in total_results) / len(total_results)
    support_fraction = sum(result["support_fraction"] for result in total_results) / len(total_results)

    if support_fraction >= 0.8:
        print(f"RESULT: SUPPORTED mean={mean_metric_value} std=0 support_fraction={support_fraction}")
    else:
        first_failing_seed = min(total_results, key=lambda x: x["support_fraction"])["seed"]
        print(f"RESULT: FALSIFIED counterexample=\"not supported\" first_failing_seed={first_failing_seed}")

import random
import math
import json
from itertools import product, combinations

def generate_monomial(n):
    return tuple(random.choice([0, 1]) for _ in range(n))

def generate_threshold_function(n, k):
    minterms = list(product([0, 1], repeat=n))
    selected_minterms = random.sample(minterms, k)
    return lambda x: any(x[i] == m[i] for i, m in enumerate(selected_minterms))

def generate_monotone_2cnf(n):
    variables = set(range(n))
    clauses = []
    for _ in range(10):  # Generate a few random clauses
        clause = random.sample(variables, 2)
        clauses.append((clause[0], clause[1]))
    return lambda x: all(x[v] or not x[u] for u, v in clauses)

def generate_recursive_majority(n):
    if n == 3:
        return lambda x: (x[0] and x[1]) or (not x[0] and not x[2])
    else:
        subformula = generate_recursive_majority(n - 1)
        return lambda x: subformula(x[:n-1]) and (x[n-1] == 1)

def build_bipartite_graph(f):
    n = len(next(iter(f.keys())))
    minterms = list(product([0, 1], repeat=n))
    maxterms = [tuple(1 - m[i] for i in range(n)) for m in minterms]

    graph = {}
    for m in minterms:
        if m not in graph:
            graph[m] = set()
        for mt in maxterms:
            if mt not in graph:
                graph[mt] = set()
            if sum(m[i] != mt[i] for i in range(n)) == 1 and f(mt) == 1:
                graph[m].add(mt)
                graph[mt].add(m)

    return graph

def bfs_diameter(graph, start):
    queue = [start]
    visited = {start}
    distance = {start: 0}
    max_distance = 0

    while queue:
        current = queue.pop(0)
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                distance[neighbor] = distance[current] + 1
                max_distance = max(max_distance, distance[neighbor])
                queue.append(neighbor)

    return max_distance

def monotone_kw_depth(f):
    n = len(next(iter(f.keys())))
    memo = {}

    def minimax(state, depth=0):
        if state in memo:
            return memo[state]

        if all(f[i] for i in range(n)):
            return depth

        min_val = float('inf')
        for i in range(n):
            new_state = list(state)
            new_state[i] = 1 - new_state[i]
            min_val = min(min_val, minimax(tuple(new_state), depth + 1))

        memo[state] = min_val
        return min_val

    return minimax((0,) * n)

def run_trial(seed: int) -> dict:
    random.seed(seed)

    n_values = [5, 8, 11, 14]
    results = []

    for n in n_values:
        if n == 3:
            f = generate_threshold_function(n, 2)
        elif n == 8:
            f = generate_monotone_2cnf(n)
        elif n == 11:
            f = generate_recursive_majority(3)
        else:
            return {
                "metric_name": "monotone-KW depth",
                "metric_value": None,
                "instances_tested": 0,
                "conjecture_holds": False,
                "counterexample": "mapping_undefined"
            }

        B_f = build_bipartite_graph(f)
        D_TS = bfs_diameter(B_f, (0,) * n)
        D_m = monotone_kw_depth(f)

        results.append({
            "n": n,
            "D_TS": D_TS,
            "D_m": D_m
        })

    if not results:
        return {
            "metric_name": "monotone-KW depth",
            "metric_value": None,
            "instances_tested": 0,
            "conjecture_holds": False,
            "counterexample": "mapping_undefined"
        }

    D_TS_values = [r["D_TS"] for r in results]
    D_m_values = [r["D_m"] for r in results]

    if all(D_m >= math.log2(D_TS + 1) - 1 for D_m, D_TS in zip(D_m_values, D_TS_values)):
        slope, intercept = linear_regression(D_TS_values, D_m_values)
        if slope >= 0.9 and intercept >= -1.5:
            return {
                "metric_name": "monotone-KW depth",
                "metric_value": None,
                "instances_tested": len(results),
                "conjecture_holds": True,
                "counterexample": ""
            }

    for r in results:
        if r["D_m"] < math.log2(r["D_TS"] + 1) - 1:
            return {
                "metric_name": "monotone-KW depth",
                "metric_value": None,
                "instances_tested": len(results),
                "conjecture_holds": False,
                "counterexample": f"Depth {r['D_m']} < log2({r['D_TS']}+1) - 1 for n={r['n']}"
            }

    return {
        "metric_name": "monotone-KW depth",
        "metric_value": None,
        "instances_tested": len(results),
        "conjecture_holds": False,
        "counterexample": "mapping_undefined"
    }

def linear_regression(x, y):
    n = len(x)
    sum_x = sum(x)
    sum_y = sum(y)
    sum_xy = sum(xi * yi for xi, yi in zip(x, y))
    sum_xx = sum(xi ** 2 for xi in x)

    slope = (n * sum_xy - sum_x * sum_y) / (n * sum_xx - sum_x ** 2)
    intercept = (sum_y - slope * sum_x) / n

    return slope, intercept

if __name__ == "__main__":
    seeds = [int(x) for x in sys.argv[1:]] or [11, 23, 37, 53, 71]

    for seed in seeds:
        result = run_trial(seed)
        print(json.dumps({"TRIAL": {"seed": seed, **result}}))

