    return {
        "metric_name": "ψ(F)",
        "metric_value": psi_F,
        "instances_tested": 1,
        "conjecture_holds": psi_F >= log2_L_T,
        "counterexample": "" if psi_F >= log2_L_T else f"psi_F={psi_F}, log2(L_T)={log2_L_T}"
    }

