    std_log2_L_TF = math.sqrt(sum((log2_L_TF - mean_log2_L_TF) ** 2 for _, log2_L_TF, _ in results) / len(results))
    support_fraction = sum(1 for _, log2_L_TF, defect in results if log2_L_TF >= (defect + 1) / 4) / len(results)

    return {
