            rank_M = matrix_rank(M, tolerance=1e-8)
            rows = [''.join(str(bit) for bit in row) for row in M]
            p_r_x_values = [subword_complexity(row, k) for row in rows]
            s_f = max(p_r_x_values)

            if rank_M < s_f:
                conjecture_holds = False
